void Solver::rephase() {
    // Reset the rephase counter.
    rephases = 0;

    // Make the next rephase a bit harder to trigger by increasing the threshold.
    // Use the current trail size as a baseline and add a small margin.
    threshold = std::max(threshold, (int)trail.size() + (int)(0.1 * trail.size()));

    // Gradually raise the limit so we don't rephase too frequently.
    // A 20% increase works well in practice.
    rephase_limit = (int)(rephase_limit * 1.2);

    // Decide which phase to use for each variable.
    // If recent LBD statistics look promising (fast average < slow average),
    // keep the locally best phase; otherwise invert it.
    bool use_best = (lbd_queue_size > 0) &&
                    ((fast_lbd_sum / (double)lbd_queue_size) <
                     (slow_lbd_sum / (double)std::max(1, conflicts)));

    for (int i = 1; i <= vars; ++i) {
        if (use_best) {
            saved[i] = local_best[i];          // keep the best local phase
        } else {
            saved[i] = -local_best[i];         // invert the best local phase
        }
    }

    // Occasionally inject some randomness to escape stagnation.
    if (rand() % 100 < 5) { // 5% chance
        for (int i = 1; i <= vars; ++i) {
            saved[i] = (rand() & 1) ? 1 : -1; // random polarity
        }
    }

    // Finally, backtrack to the root level to apply the new phases.
    backtrack(0);
}
